287:   function analyzeFrequencyBands(id, sampleRate) {
288:     const deck = decks[id];
289:     const bins = deck.data.length;
290:     const maxHz = sampleRate / 2;
291:     const ranges = { low: [40, 250], mid: [250, Math.min(4000, maxHz)], high: [Math.min(4000, maxHz - 1), maxHz] };
292:     for (const [name, [lo, hi]] of Object.entries(ranges)) {
293:       const start = Math.max(0, Math.floor(lo / maxHz * bins));
294:       const end = Math.max(start + 1, Math.min(bins, Math.floor(hi / maxHz * bins)));
295:       let energy = 0;
296:       for (let i = start; i < end; i++) energy += deck.data[i] / 255;
297:       deck.bandLevels[name] = energy / (end - start);
298:       $(`#band-${name}-${id}`).textContent = `${Math.round(deck.bandLevels[name] * 100)}%`;
299:     }
300:     if (deck.audio.currentTime > 0.08 && deck.audio.currentTime < (deck.audio.duration || Infinity) - 0.08) {
301:       const lowEnergy = deck.bandLevels.low;
302:       deck.bpmSamples.push({ time: deck.audio.currentTime, energy: lowEnergy });
303:       const cutoff = deck.audio.currentTime - 12;
304:       while (deck.bpmSamples.length && deck.bpmSamples[0].time < cutoff) deck.bpmSamples.shift();
305:       estimateBpmFromEnergy(id);
306:     }
307:   }
