376:   function renderWave(id) {
377:     const deck = decks[id];
378:     const canvas = $(`#wave-${id}`);
379:     const ctx = canvas.getContext('2d');
380:     const width = canvas.clientWidth || 500;
381:     const height = canvas.clientHeight || 67;
382:     const ratio = Math.min(window.devicePixelRatio || 1, 2);
383:     if (canvas.width !== Math.floor(width * ratio) || canvas.height !== Math.floor(height * ratio)) {
384:       canvas.width = Math.floor(width * ratio); canvas.height = Math.floor(height * ratio);
385:     }
386:     ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
387:     ctx.clearRect(0, 0, width, height);
388:     ctx.fillStyle = '#0c1016'; ctx.fillRect(0, 0, width, height);
389:     ctx.strokeStyle = '#202630'; ctx.lineWidth = 1;
390:     ctx.beginPath(); ctx.moveTo(0, height / 2); ctx.lineTo(width, height / 2); ctx.stroke();
391:     const colors = ['#fa596d', '#72e294', '#57aef4'];
392:     const bands = [[0, 250], [250, 4000], [4000, 12000]];
393:     const sampleRate = audioContext?.sampleRate || 44100;
394:     const bins = deck.data.length;
395:     const maxHz = sampleRate / 2;
396:     const active = Boolean(deck.analyser && !deck.audio.paused && deck.audio.src && !deck.audio.src.startsWith('https://www.youtube'));
397:     if (active) {
398:       deck.analyser.getByteFrequencyData(deck.data);
399:       analyzeFrequencyBands(id, sampleRate);
400:     }
401:     const columns = Math.max(1, Math.floor(width / 3));
402:     const offset = deck.audio.currentTime ? Math.floor(deck.audio.currentTime * 14) % columns : 0;
403:     for (let x = 0; x < columns; x++) {
404:       const pos = (x + offset) % columns;
405:       let total = 0;
406:       for (let band = 0; band < bands.length; band++) {
407:         const [lo, hi] = bands[band];
408:         const start = Math.max(0, Math.floor(lo / maxHz * bins));
409:         const end = Math.max(start + 1, Math.min(bins, Math.floor(hi / maxHz * bins)));
410:         let energy = 0;
411:         if (active) {
412:           for (let i = start; i < end; i++) energy += deck.data[i];
413:           energy /= (end - start) * 255;
414:         } else {
415:           const wave = Math.sin((pos * 0.083) + band * 1.7 + (id === 'b' ? 0.8 : 0));
416:           energy = deck.audio.src ? 0.12 + Math.abs(wave) * 0.2 : 0.035;
417:         }
418:         const barHeight = Math.max(2, energy * height * 0.75);
419:         const alpha = active ? 0.42 + Math.min(0.55, energy) : 0.20;
420:         ctx.globalAlpha = alpha;
421:         ctx.fillStyle = colors[band];
422:         const yOffset = band === 0 ? -1 : band === 1 ? 0 : 1;
423:         ctx.fillRect(pos * 3, (height - barHeight) / 2 + yOffset * 5, 2, barHeight);
424:         total += energy;
425:       }
426:       if (active && total > 0.14) {
427:         ctx.globalAlpha = 0.25;
428:         ctx.fillStyle = id === 'a' ? '#54e3dc' : '#ff4e97';
429:         ctx.fillRect(pos * 3, 0, 1, height);
430:       }
431:     }
432:     ctx.globalAlpha = 1;
433:     const progress = deck.audio.duration ? deck.audio.currentTime / deck.audio.duration : 0;
434:     const playX = progress * width;
435:     ctx.fillStyle = id === 'a' ? '#dcfff9' : '#ffe0ed';
436:     ctx.shadowColor = id === 'a' ? '#54e3dc' : '#ff4e97'; ctx.shadowBlur = 7;
437:     ctx.fillRect(playX, 0, 1, height); ctx.shadowBlur = 0;
438:     $(`#time-${id}`).textContent = `${formatTime(deck.audio.currentTime || 0)} / ${formatTime(deck.audio.duration)}`;
