453:   function measurePhaseOffset(a, b) {
454:     const phaseA = ((a.audio.currentTime * a.bpm / 60) % 1 + 1) % 1;
455:     const phaseB = ((b.audio.currentTime * b.bpm / 60) % 1 + 1) % 1;
456:     const beatOffset = ((phaseB - phaseA + 1.5) % 1) - 0.5;
457:     return beatOffset * 60000 / Math.max(1, (a.bpm + b.bpm) / 2);
458:   }
