763:   function handleMidi(event) {
764:     const [status, data1, data2] = event.data;
765:     const command = status & 0xf0;
766:     const channel = status & 0x0f;
767:     const isNote = command === 0x90 && data2 > 0;
768:     const isCC = command === 0xb0;
769:     if (midiLearnEnabled && (isNote || isCC)) {
770:       const target = $('#midi-target-select').value;
771:       midiMap[target] = { type: isNote ? 'note' : 'cc', number: data1, channel };
772:       midiLearnEnabled = false;
773:       midiLearnTarget = null;
774:       persistMidiMap();
775:       updateMidiLearnStatus();
776:       toast(`${MIDI_LABELS[target] || target}: ${midiMessageLabel(midiMap[target])}`);
777:       return;
778:     }
779:     for (const [target, mapping] of Object.entries(midiMap)) {
780:       if (!mapping || mapping.channel !== channel || data1 !== mapping.number) continue;
781:       if (mapping.type === 'note' && isNote) {
782:         if (target.startsWith('play-')) playDeck(target.slice(-1));
783:         else if (target.startsWith('cue-')) cueDeck(target.slice(-1));
784:         else if (target.startsWith('sync-')) syncDeck(target.slice(-1));
785:         else if (target.startsWith('jog-')) nudgeDeck(target.slice(-1), 0.025);
786:       } else if (mapping.type === 'cc' && isCC) {
787:         dispatchMidiControl(target, data2);
788:       }
789:     }
790:   }
