792:   function dispatchMidiControl(target, value) {
793:     if (value > 0 && target.startsWith('play-')) { playDeck(target.slice(-1)); return; }
794:     if (value > 0 && target.startsWith('cue-')) { cueDeck(target.slice(-1)); return; }
795:     if (value > 0 && target.startsWith('sync-')) { syncDeck(target.slice(-1)); return; }
796:     if (target.startsWith('jog-')) {
797:       const delta = value > 64 ? value - 128 : value;
798:       if (delta) nudgeDeck(target.slice(-1), Math.sign(delta) * Math.min(Math.abs(delta), 8) * 0.012);
799:       return;
800:     }
801:     const controls = {
802:       'volume-a': $('[data-volume="a"]'), 'volume-b': $('[data-volume="b"]'),
803:       'pitch-a': $('[data-pitch="a"]'), 'pitch-b': $('[data-pitch="b"]'),
804:       'eq-a-low': $('[data-eq="low"][data-deck="a"]'), 'eq-a-mid': $('[data-eq="mid"][data-deck="a"]'), 'eq-a-high': $('[data-eq="high"][data-deck="a"]'),
805:       'eq-b-low': $('[data-eq="low"][data-deck="b"]'), 'eq-b-mid': $('[data-eq="mid"][data-deck="b"]'), 'eq-b-high': $('[data-eq="high"][data-deck="b"]'),
806:       crossfader: $('#crossfader')
807:     };
808:     const input = controls[target];
809:     if (!input) return;
810:     const min = Number(input.min || 0), max = Number(input.max || 127);
811:     input.value = String(min + (value / 127) * (max - min));
812:     input.dispatchEvent(new Event('input', { bubbles: true }));
813:   }
