841:     const ctx = canvas.getContext('2d');
842:     const width = canvas.clientWidth || 500, height = canvas.clientHeight || 67;
843:     const ratio = Math.min(window.devicePixelRatio || 1, 2);
844:     if (canvas.width !== Math.floor(width * ratio) || canvas.height !== Math.floor(height * ratio)) { canvas.width = Math.floor(width * ratio); canvas.height = Math.floor(height * ratio); }
845:     ctx.setTransform(ratio, 0, 0, ratio, 0, 0); ctx.clearRect(0, 0, width, height); ctx.fillStyle = '#0c1016'; ctx.fillRect(0, 0, width, height);
846:     const colors = ['#fa596d', '#72e294', '#57aef4'];
847:     for (let x = 0; x < width; x += 3) {
848:       const rhythm = Math.abs(Math.sin(x * 0.045 + (id === 'b' ? 1 : 0)) * Math.cos(x * 0.012));
